// Send a Gmail message via Nango OAuth, then record a note.
// Executor wraps this body as (async function(args, context){ <code> }); use args
// directly and `return`. callProvider('gmail', 'POST',
// '/gmail/v1/users/me/messages/send', { raw }) goes through the dispatcher by
// tool NAME ('gmail'): the dispatcher resolves the tool's credentialRef
// (nango://gmail), the nango:// handler resolves the user's Google connection and
// proxies to the Gmail API. (Passing the raw credentialRef 'nango://gmail' still
// works too — back-compat.)
const to = String(args?.to ?? '').trim();
const subject = String(args?.subject ?? '').trim();
const bodyText = String(args?.body ?? '');
if (!to) throw new Error('gmail_send: to is required');
if (!subject) throw new Error('gmail_send: subject is required');

// Build an RFC 2822 message and base64url-encode it (Gmail raw field).
// No Buffer/btoa in the isolate, so encode UTF-8 -> base64 manually.
const mime = [
  'To: ' + to,
  'Subject: ' + subject,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset="UTF-8"',
  '',
  bodyText
].join('\r\n');

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const utf8Bytes = (str) => {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) { out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f)); }
    else if (c >= 0xd800 && c <= 0xdbff) {
      const c2 = str.charCodeAt(++i);
      c = 0x10000 + ((c & 0x3ff) << 10) + (c2 & 0x3ff);
      out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 0x3f), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    } else { out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f)); }
  }
  return out;
};
const base64 = (bytes) => {
  let s = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i], b1 = bytes[i + 1], b2 = bytes[i + 2];
    s += B64[b0 >> 2];
    s += B64[((b0 & 3) << 4) | ((b1 ?? 0) >> 4)];
    s += b1 === undefined ? '=' : B64[((b1 & 15) << 2) | ((b2 ?? 0) >> 6)];
    s += b2 === undefined ? '=' : B64[b2 & 63];
  }
  return s;
};
const raw = base64(utf8Bytes(mime)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

const res = await callProvider('gmail', 'POST', '/gmail/v1/users/me/messages/send', { raw });
const ok = res?.status ? res.status >= 200 && res.status < 300 : true;
const messageId = res?.body?.id ?? null;

await propose.entity({
  profileSlug: 'note',
  title: 'Email ' + (ok ? 'sent' : 'attempted') + ' -> ' + to + ': ' + subject,
  properties: {
    action: 'gmail_send',
    to,
    subject,
    gmailMessageId: messageId,
    status: res?.status ?? null,
    success: ok,
    source: 'nango-gmail'
  },
  reasoning: 'Recorded the outbound follow-up email for the activity timeline.'
});
return { success: ok, to, subject, gmailMessageId: messageId, status: res?.status ?? null };
